<?php if(!defined('APP_ENTRY'))exit; $role=$user['role'];$teacher=$role==='teacher';$uid=(int)$user['id'];
if($_SERVER['REQUEST_METHOD']==='POST'){if(!$teacher)deny();try{ $action=post('action'); transaction(function()use($action,$uid){if($action==='save'){ $en=id_field('enrollment_id');$score=filter_var(post('score'),FILTER_VALIDATE_FLOAT);if($score===false||!is_finite($score)||$score<0||$score>100||!preg_match('/^\d{1,3}(\.\d{1,2})?$/D',post('score')))throw new DomainException('Enter a score from 0 to 100, with up to two decimal places.');$r=one('SELECT e.id FROM enrollments e JOIN classes c ON c.id=e.class_id WHERE e.id=? AND c.teacher_id=? FOR UPDATE',[$en,$uid]);if(!$r)deny();execute('INSERT INTO grades(enrollment_id,score,recorded_by) VALUES(?,?,?) ON DUPLICATE KEY UPDATE score=VALUES(score),recorded_by=VALUES(recorded_by),updated_at=CURRENT_TIMESTAMP',[$en,$score,$uid]);audit('grade saved',"enrollment #$en");}elseif($action==='delete'){confirmed();$id=id_field('id');$r=one('SELECT g.id FROM grades g JOIN enrollments e ON e.id=g.enrollment_id JOIN classes c ON c.id=e.class_id WHERE g.id=? AND c.teacher_id=? FOR UPDATE',[$id,$uid]);if(!$r)deny();execute('DELETE FROM grades WHERE id=?',[$id]);audit('grade deleted',"grade #$id");}else deny();});flash('Grade updated.');redirect('grades');}catch(DomainException $ex){$error=$ex->getMessage();}catch(PDOException $ex){error_log_file($ex);$error='Unable to save the grade.';}}
$q='%'.search_term().'%';$sql='SELECT g.id,g.score,g.updated_at,e.id enrollment_id,s.name,c.class_name,COALESCE(t.name,\'Legacy import\') recorded_by FROM enrollments e JOIN students s ON s.id=e.student_id JOIN classes c ON c.id=e.class_id LEFT JOIN grades g ON g.enrollment_id=e.id LEFT JOIN staff_accounts t ON t.id=g.recorded_by WHERE (s.name LIKE ? OR c.class_name LIKE ?)';$params=[$q,$q];if($teacher){$sql.=' AND c.teacher_id=?';$params[]=$uid;}elseif($role==='student'){$sql.=' AND e.student_id=?';$params[]=$user['student_id'];}$data=rows($sql.' ORDER BY c.class_name,s.name',$params);$edit=filter_var(query('edit'),FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$editing=[];if($teacher&&$edit){$editing=one('SELECT g.score,g.enrollment_id FROM grades g JOIN enrollments e ON e.id=g.enrollment_id JOIN classes c ON c.id=e.class_id WHERE g.id=? AND c.teacher_id=?',[$edit,$uid]);if(!$editing)missing();}$opts=$teacher?rows('SELECT e.id,s.name,c.class_name FROM enrollments e JOIN students s ON s.id=e.student_id JOIN classes c ON c.id=e.class_id WHERE c.teacher_id=? ORDER BY c.class_name,s.name',[$uid]):[]; ?>
<?php if($error):?><div class="error"><?=e($error)?></div><?php endif;?><?php if($teacher):?><section class="panel"><h2><?=$edit?'Edit grade':'Record or update a grade'?></h2><p class="muted">Only your assigned classes are available. Saving an existing enrollment replaces its score.</p><form class="grid-form" method="post" action="<?=e(url('grades',$edit?['edit'=>$edit]:[]))?>"><?=csrf_field()?><input type="hidden" name="action" value="save"><label>Student / class<select name="enrollment_id" required><option value="">Choose enrollment</option><?php foreach($opts as $o):?><option value="<?=$o['id']?>"<?=selected(post('enrollment_id')?:($editing['enrollment_id']??''),$o['id'])?>><?=e($o['name'].' — '.$o['class_name'])?></option><?php endforeach;?></select></label><label>Score (0–100)<input type="number" min="0" max="100" step="0.01" name="score" value="<?=val('score',$editing)?>" required></label><div class="form-actions"><button>Save grade</button><?php if($edit):?><a class="button secondary" href="<?=e(url('grades'))?>">Cancel</a><?php endif;?></div></form></section><?php endif;?>
<section class="panel"><div class="toolbar"><h2><?=$role==='student'?'My grades':'Academic grades'?></h2><?php search_form($page);?></div><div class="table-wrap"><table><thead><tr><?php if($role!=='student'):?><th>Student</th><?php endif;?><th>Class</th><th>Score</th><th>Last updated</th><?php if($role!=='student'):?><th>Recorded by</th><?php endif;?><?php if($teacher):?><th>Actions</th><?php endif;?></tr></thead><tbody><?php foreach($data as $r):?><tr><?php if($role!=='student'):?><td><?=e($r['name'])?></td><?php endif;?><td><?=e($r['class_name'])?></td><td><span class="pill"><?=e($r['score']??'Not graded')?></span></td><td><?=e($r['updated_at']??'—')?></td><?php if($role!=='student'):?><td><?=e($r['id']?$r['recorded_by']:'—')?></td><?php endif;?><?php if($teacher):?><td><?php if($r['id']):?><div class="inline"><a class="button secondary" href="<?=e(url('grades',['edit'=>$r['id']]))?>">Edit</a><?php delete_form('grades',(int)$r['id']);?></div><?php else:?>Use form above<?php endif;?></td><?php endif;?></tr><?php endforeach;?><?php if(!$data):?><tr><td colspan="6">No matching enrollments.</td></tr><?php endif;?></tbody></table></div></section>
